import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
_cpp_src = r"""
torch::Tensor sdpa_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V);
"""
_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cuda_fp16.h>
#include <cuda_pipeline.h>
#include <mma.h>
#include <cmath>
#include <algorithm>
namespace {
using namespace nvcuda;
constexpr int BR = 32;       // query rows per block: two 16-row mma bands per CTA
constexpr int BN = 64;       // keys per inner tile (4 x 16-wide n-fragments)
constexpr int THREADS = 256; // 8 warps: (2 row bands) x (4 key fragments) for S
constexpr int NWARPS = THREADS / 32;
constexpr int DCHUNK = 32;   // Q/K slabs staged in shared memory with cp.async double buffering
constexpr int SS_LD = BN + 8;   // padded sS row stride (floats): bank-skewed, 32B-aligned rows
constexpr int SP_LD = BN + 16;  // padded sP row stride (halves): bank-skewed, 32B-aligned rows
constexpr int ACC_SKEW = 8;     // acc row padding (floats): breaks 4096B-stride bank conflicts
__device__ __forceinline__ void load_tile_async(
    const __half* __restrict__ base,
    __half* __restrict__ dst,
    const int row0,
    const int kc,
    const int D,
    const int rows,
    const int klen,
    const int tid) {
  const int chunks_per_row = klen >> 3;  // 16-byte cp.async transactions per row
  const int total = rows * chunks_per_row;
  for (int idx = tid; idx < total; idx += THREADS) {
    const int r = idx / chunks_per_row;
    const int cc = idx - r * chunks_per_row;
    const __half* src = base + static_cast<size_t>(row0 + r) * D + kc + (cc << 3);
    __half* out = dst + r * DCHUNK + (cc << 3);
    __pipeline_memcpy_async(out, src, 16);
  }
}
__device__ __forceinline__ void load_qk_chunk_async(
    const __half* __restrict__ Qb,
    const __half* __restrict__ Kb,
    __half* __restrict__ sQ,
    __half* __restrict__ sK,
    const int q0,
    const int k0,
    const int kc,
    const int D,
    const int klen,
    const int tid) {
  load_tile_async(Qb, sQ, q0, kc, D, BR, klen, tid);
  load_tile_async(Kb, sK, k0, kc, D, BN, klen, tid);
  __pipeline_commit();
}
__global__ void fused_sdpa_kernel(
    const __half* __restrict__ Q,
    const __half* __restrict__ K,
    const __half* __restrict__ V,
    __half* __restrict__ out,
    const int B,
    const int H,
    const int L,
    const int D,
    const int d_tile,
    const float scale) {
  extern __shared__ __align__(32) char smem_raw[];
  float* acc = reinterpret_cast<float*>(smem_raw);          // BR * (d_tile + ACC_SKEW)
  float* sS = acc + BR * (d_tile + ACC_SKEW);                // BR * BN padded rows
  __half* sP = reinterpret_cast<__half*>(sS + BR * SS_LD);   // BR * BN padded rows
  float* m = reinterpret_cast<float*>(sP + BR * SP_LD);      // BR
  float* l = m + BR;                                         // BR
  float* alpha = l + BR;                                     // BR
  __half* sK = reinterpret_cast<__half*>(alpha + BR);        // 2 * BN * DCHUNK
  __half* sQ = sK + 2 * BN * DCHUNK;                         // 2 * BR * DCHUNK
  const int tid = threadIdx.x;
  const int warp = tid >> 5;
  const int bh = blockIdx.y;
  const int q0 = blockIdx.x * BR;
  const int d0 = blockIdx.z * d_tile;
  const int dlen = d_tile < (D - d0) ? d_tile : (D - d0);
  const int acc_ld = dlen + ACC_SKEW;
  const size_t bh_stride = static_cast<size_t>(L) * D;
  const __half* Qb = Q + static_cast<size_t>(bh) * bh_stride;
  const __half* Kb = K + static_cast<size_t>(bh) * bh_stride;
  const __half* Vb = V + static_cast<size_t>(bh) * bh_stride;
  __half* Ob = out + static_cast<size_t>(bh) * bh_stride;
  if (tid < BR) {
    m[tid] = -INFINITY;
    l[tid] = 0.0f;
    alpha[tid] = 0.0f;
  }
  for (int idx = tid; idx < BR * dlen; idx += THREADS) {
    const int r = idx / dlen;
    acc[r * acc_ld + (idx - r * dlen)] = 0.0f;
  }
  __syncthreads();
  for (int k0 = 0; k0 < L; k0 += BN) {
    // ---- S = Q_tile @ K_tile^T via tensor cores (fp16 in, fp32 acc) ----
    {
      const int rb = warp >> 2;  // BR/16 == 2 row bands
      const int nf = warp & 3;   // BN/16 == 4 key fragments
      wmma::fragment<wmma::accumulator, 16, 16, 16, float> c;
      wmma::fill_fragment(c, 0.0f);
      const int first_len = (DCHUNK < D) ? DCHUNK : D;
      load_qk_chunk_async(Qb, Kb, sQ, sK, q0, k0, 0, D, first_len, tid);
      for (int kc = 0; kc < D; kc += DCHUNK) {
        const int buf = (kc / DCHUNK) & 1;
        const int klen = (DCHUNK < (D - kc)) ? DCHUNK : (D - kc);
        const int kn = kc + DCHUNK;
        if (kn < D) {
          const int nlen = (DCHUNK < (D - kn)) ? DCHUNK : (D - kn);
          load_qk_chunk_async(Qb, Kb, sQ + (buf ^ 1) * BR * DCHUNK, sK + (buf ^ 1) * BN * DCHUNK, q0, k0, kn, D, nlen, tid);
          __pipeline_wait_prior(1);
        } else {
          __pipeline_wait_prior(0);
        }
        __syncthreads();
        const __half* qb = sQ + buf * BR * DCHUNK;
        const __half* kb = sK + buf * BN * DCHUNK;
        for (int ks = 0; ks < klen; ks += 16) {
          wmma::fragment<wmma::matrix_a, 16, 16, 16, __half, wmma::row_major> af;
          wmma::fragment<wmma::matrix_b, 16, 16, 16, __half, wmma::col_major> bf;
          wmma::load_matrix_sync(af, qb + (rb * 16) * DCHUNK + ks, DCHUNK);
          // col_major B reads row-major shared K as K^T: elem(kk,j)=sK[k0+nf*16+j][ks+kk]
          wmma::load_matrix_sync(bf, kb + (nf * 16) * DCHUNK + ks, DCHUNK);
          wmma::mma_sync(c, af, bf, c);
        }
        __syncthreads();
      }
      wmma::store_matrix_sync(sS + (rb * 16) * SS_LD + nf * 16, c, SS_LD, wmma::mem_row_major);
    }
    __syncthreads();
    // ---- online softmax update for this key tile ----
    if (tid < BR) {
      const int base = tid * SS_LD;
      const int pbase = tid * SP_LD;
      const float old_m = m[tid];
      const float old_l = l[tid];
      float new_m = old_m;
      #pragma unroll
      for (int j = 0; j < BN; ++j) {
        const float sc = sS[base + j] * scale;
        new_m = sc > new_m ? sc : new_m;
      }
      const float a = (old_l == 0.0f) ? 0.0f : __expf(old_m - new_m);
      float new_l = old_l * a;
      #pragma unroll
      for (int j = 0; j < BN; ++j) {
        const float e = __expf(sS[base + j] * scale - new_m);
        sP[pbase + j] = __float2half(e);
        new_l += e;
      }
      m[tid] = new_m;
      l[tid] = new_l;
      alpha[tid] = a;
    }
    __syncthreads();
    // rescale running accumulator
    for (int idx = tid; idx < BR * dlen; idx += THREADS) {
      const int r = idx / dlen;
      acc[r * acc_ld + (idx - r * dlen)] *= alpha[r];
    }
    __syncthreads();
    // ---- acc += P_tile @ V_tile via tensor cores, split over row bands and head dim ----
    {
      const int dfrags = dlen >> 4;
      const int total_frags = (BR >> 4) * dfrags;
      for (int f = warp; f < total_frags; f += NWARPS) {
        const int rb = f / dfrags;
        const int nfrag = f - rb * dfrags;
        const int n0 = nfrag << 4;
        wmma::fragment<wmma::accumulator, 16, 16, 16, float> c;
        wmma::load_matrix_sync(c, acc + (rb * 16) * acc_ld + n0, acc_ld, wmma::mem_row_major);
        #pragma unroll
        for (int kf = 0; kf < BN; kf += 16) {
          wmma::fragment<wmma::matrix_a, 16, 16, 16, __half, wmma::row_major> af;
          wmma::fragment<wmma::matrix_b, 16, 16, 16, __half, wmma::row_major> bf;
          wmma::load_matrix_sync(af, sP + (rb * 16) * SP_LD + kf, SP_LD);
          wmma::load_matrix_sync(bf, Vb + static_cast<size_t>(k0 + kf) * D + d0 + n0, D);
          wmma::mma_sync(c, af, bf, c);
        }
        wmma::store_matrix_sync(acc + (rb * 16) * acc_ld + n0, c, acc_ld, wmma::mem_row_major);
      }
    }
    __syncthreads();
  }
  for (int idx = tid; idx < BR * dlen; idx += THREADS) {
    const int r = idx / dlen;
    const int c = idx - r * dlen;
    const float inv_l = 1.0f / l[r];
    Ob[static_cast<size_t>(q0 + r) * D + d0 + c] =
        __float2half_rn(acc[r * acc_ld + c] * inv_l);
  }
}
inline size_t non_acc_smem_bytes() {
  return static_cast<size_t>(BR) * SS_LD * sizeof(float) +
         static_cast<size_t>(BR) * SP_LD * sizeof(__half) +
         static_cast<size_t>(3 * BR) * sizeof(float) +
         static_cast<size_t>(2 * BN * DCHUNK) * sizeof(__half) +
         static_cast<size_t>(2 * BR * DCHUNK) * sizeof(__half);
}
inline size_t smem_bytes(const int d_tile) {
  return static_cast<size_t>(BR) * (d_tile + ACC_SKEW) * sizeof(float) +
         non_acc_smem_bytes();
}
}  // namespace
torch::Tensor sdpa_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
  TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(), "Q, K, V must be CUDA tensors");
  TORCH_CHECK(Q.scalar_type() == at::kHalf && K.scalar_type() == at::kHalf && V.scalar_type() == at::kHalf,
              "Q, K, V must be float16");
  TORCH_CHECK(Q.dim() == 4 && K.dim() == 4 && V.dim() == 4, "Q, K, V must be 4D");
  TORCH_CHECK(Q.size(0) == K.size(0) && Q.size(0) == V.size(0), "batch mismatch");
  TORCH_CHECK(Q.size(1) == K.size(1) && Q.size(1) == V.size(1), "head mismatch");
  TORCH_CHECK(Q.size(2) == K.size(2) && Q.size(2) == V.size(2), "sequence mismatch");
  TORCH_CHECK(Q.size(3) == K.size(3) && Q.size(3) == V.size(3), "embedding mismatch");
  TORCH_CHECK(Q.is_contiguous() && K.is_contiguous() && V.is_contiguous(), "Q, K, V must be contiguous");
  const int B = static_cast<int>(Q.size(0));
  const int H = static_cast<int>(Q.size(1));
  const int L = static_cast<int>(Q.size(2));
  const int D = static_cast<int>(Q.size(3));
  TORCH_CHECK(L % BR == 0, "sequence length must be divisible by 32");
  TORCH_CHECK(L % BN == 0, "sequence length must be divisible by 64");
  TORCH_CHECK(D % 16 == 0, "embedding dimension must be divisible by 16");
  auto out = at::empty_like(Q);
  const float scale = static_cast<float>(1.0 / std::sqrt(static_cast<double>(D)));
  const auto* prop = at::cuda::getCurrentDeviceProperties();
  const size_t optin = static_cast<size_t>(prop->sharedMemPerBlockOptin);
  const size_t fixed_smem = non_acc_smem_bytes();
  TORCH_CHECK(
      optin >= fixed_smem +
                  static_cast<size_t>(BR) * (16 + ACC_SKEW) * sizeof(float),
      "insufficient shared memory for even a 16-wide D tile");
  size_t max_d_tile =
      (optin - fixed_smem) /
      (static_cast<size_t>(BR) * sizeof(float));
  max_d_tile = max_d_tile > static_cast<size_t>(ACC_SKEW)
                   ? max_d_tile - ACC_SKEW
                   : 0;
  max_d_tile = (max_d_tile / 16) * 16;
  TORCH_CHECK(max_d_tile >= 16, "invalid shared-memory D tile");
  const int d_tile = static_cast<int>(
      std::min<size_t>(static_cast<size_t>(D), max_d_tile));
  const size_t smem = smem_bytes(d_tile);
  const int d_tiles = (D + d_tile - 1) / d_tile;
  TORCH_CHECK(d_tiles <= 65535, "too many D tiles for gridDim.z");
  const cudaError_t attr_err = cudaFuncSetAttribute(
      reinterpret_cast<const void*>(fused_sdpa_kernel),
      cudaFuncAttributeMaxDynamicSharedMemorySize,
      static_cast<int>(smem));
  TORCH_CHECK(attr_err == cudaSuccess, cudaGetErrorString(attr_err));
  dim3 grid(L / BR, B * H, d_tiles);
  dim3 block(THREADS);
  auto stream = at::cuda::getCurrentCUDAStream().stream();
  fused_sdpa_kernel<<<grid, block, smem, stream>>>(
      reinterpret_cast<const __half*>(Q.data_ptr<at::Half>()),
      reinterpret_cast<const __half*>(K.data_ptr<at::Half>()),
      reinterpret_cast<const __half*>(V.data_ptr<at::Half>()),
      reinterpret_cast<__half*>(out.data_ptr<at::Half>()),
      B, H, L, D, d_tile, scale);
  C10_CUDA_KERNEL_LAUNCH_CHECK();
  return out;
}
