      const int dfrags = dlen >> 4;
      const int total_frags = (BR >> 4) * dfrags;
      for (int f = warp; f < total_frags; f += NWARPS) {
        const int rb = f / dfrags;
        const int nfrag = f - rb * dfrags;
        const int n0 = nfrag << 4;
